from contextlib import contextmanager
from threading import currentThread
from taf.collectors.l1l2bip import InterfaceL1L2BIPCollectorFactory
from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import BIP_THREAD_NAME, SERVER_HOST


def start(bip_instance):
    """
    Method to start bip collection
    :param bip_instance: instance of InterfaceL1L2BIPCollectorFactory from taf.collectors.l1l2bip
    """
    try:
        bip_instance.setup()
        bip_instance.start()
    except Exception as exc:
        logger.exception(
            "Exception caught upon start bip collection. {}:{}".format(type(exc).__name__, exc), exc_info=True
        )
        bip_instance.teardown()


def stop(bip_instance, log_dir):
    """
    Method to stop bip collection and move logs to log directory
    :param bip_instance: instance of InterfaceL1L2BIPCollectorFactory from taf.collectors.l1l2bip
    :param log_dir: location where logs will be moved
    """
    try:
        bip_instance.stop()
        bip_instance.collect(target_dir=log_dir)
    except Exception as exc:
        logger.exception(
            "Exception caught upon stop bip collection. {}:{}".format(type(exc).__name__, exc), exc_info=True
        )
    finally:
        bip_instance.teardown()


@contextmanager
def bip(log_host, log_port, log_dir, interface, phy_cell_ids, **kwargs):
    # type: (str, int, str, str, List[int], Dict[str, Union[str, dict]]) -> Iterator[None]
    """
    Plugin for collecting bip traces from selected cells.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    :param log_dir: port of logger host
    :param interface: either "L1-L2" or "L2Hi-L2Lo", default value "L1-L2"
    :param phy_cell_ids: list of physical cell ids. If given ensure cell is on air before start.
                         If not given it will collect traces from all cells
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format("bip", SERVER_HOST))
    thread = currentThread()
    original_thread_name = thread.name
    thread.name = BIP_THREAD_NAME
    l1l2bip_collector = InterfaceL1L2BIPCollectorFactory().create(
        configuration={
            "name": "gnb_bip",
            "webservice": {"host": "192.168.255.1", "user": "Nemuadmin", "password": "nemuuser", "port": 443},
            "interface": interface,
            "nr_phy_cell_ids": phy_cell_ids,
            "timeout": 360,
        },
        existing_arguments={},
    )
    try:
        start(l1l2bip_collector)
        yield
    finally:
        stop(l1l2bip_collector, log_dir)
        thread.name = original_thread_name
